mapper.select:
SELECT ps.id ,ps.stock_code ,si.stock_name ,si.stock_short_name ,si.industry_code ,si.industry_name ,ratings.latest_rating ,ratings.previous_rating ,ps.target_pool_id ,p.pool_name target_pool_name ,ps.adjuster_name ,ps.entry_time ,ps.adjust_log_id ,ps.adjust_batch_no ,si.security_type ,si.market_code ,si.previous_close_price ,si.high_price ,si.low_price ,si.average_price ,si.turnover_rate ,si.trade_volume ,si.trade_market_value ,si.total_shares ,si.total_market_value ,si.circulating_a_shares ,si.a_share_market_value ,( SELECT MIN(ms.id) FROM my_security_pool ms WHERE ms.security_code = ps.stock_code AND ms.user_id = #{currentUserId} AND ms.security_type = si.security_type AND ms.market = si.market_code AND ms.status = 'use' ) my_stock_pool_id FROM ip_pool_status_stock ps INNER JOIN rrs_stockinfo si ON si.stock_code = ps.stock_code AND si.is_deleted = 0 INNER JOIN dict_security_type st ON st.security_type = si.security_type AND st.category_type = 'stock' AND st.is_deleted = 0 LEFT JOIN ip_investment_pool p ON p.id = ps.target_pool_id AND p.is_deleted = 0 LEFT JOIN ( SELECT ranked.stock_code ,MAX(CASE WHEN ranked.rating_order = 1 THEN ranked.rating_code END) latest_rating ,MAX(CASE WHEN ranked.rating_order = 2 THEN ranked.rating_code END) previous_rating FROM ( SELECT stock_code ,rating_code ,ROW_NUMBER() OVER (PARTITION BY stock_code ORDER BY rating_date DESC, id DESC) rating_order FROM rrs_stock_rating WHERE is_deleted = 0 ) ranked WHERE ranked.rating_order <= 2 GROUP BY ranked.stock_code ) ratings ON ratings.stock_code = ps.stock_code WHERE ps.is_deleted = 0 AND ps.audit_status = '20'
AND ps.target_pool_id IN
#{id}
AND ps.stock_code LIKE CONCAT('%', #{stockCode}, '%')
AND ps.entry_time >= #{entryTimeStart}
AND ps.entry_time < #{entryTimeEndExclusive}
AND ps.adjuster_name LIKE CONCAT('%', #{adjusterName}, '%')
AND EXISTS ( SELECT 1 FROM rrs_stock_manager sm WHERE sm.stock_code = ps.stock_code AND sm.user_id = #{currentUserId} AND sm.is_deleted = 0 )
AND EXISTS ( SELECT 1 FROM my_security_pool ms WHERE ms.security_code = ps.stock_code AND ms.user_id = #{currentUserId} AND ms.status = 'use' AND ms.security_type = si.security_type AND ms.market = si.market_code )
ORDER BY ps.entry_time DESC ,ps.id DESC

mapper.update:
UPDATE my_security_pool
SET status = 'del'
    ,update_time = NOW()
WHERE user_id = #{userId}
  AND security_code = #{stockCode}
  AND security_type = #{securityType}
  AND market = #{market}
  AND status = 'use'
